<script setup lang="ts">
import * as echarts from 'echarts/core'
import { LineChart, PieChart } from 'echarts/charts'
import { GridComponent, LegendComponent, TooltipComponent } from 'echarts/components'
import { CanvasRenderer } from 'echarts/renderers'
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import client from '../api/client'
import { loadSystemSettings, systemSettings } from '../stores/systemSettings'

echarts.use([LineChart, PieChart, GridComponent, LegendComponent, TooltipComponent, CanvasRenderer])

const root=ref<HTMLElement>(),trendEl=ref<HTMLElement>(),typeEl=ref<HTMLElement>(),data=ref<any>({states:{},latest_monitors:[],recent_incidents:[],probe_stats_24h:{}}),results=ref<any[]>([]),sla=ref<any[]>([]),now=ref(new Date()),updated=ref(''),connected=ref(false),error=ref('')
let trend:any,typeChart:any,timer:number|undefined,clock:number|undefined,socket:WebSocket|undefined,reconnectTimer:number|undefined,reloadTimer:number|undefined,requestVersion=0,stopped=false
const stateText:Record<string,string>={UP:'正常',DOWN:'故障',DEGRADED:'降级',MAINTENANCE:'维护',PAUSED:'暂停',PENDING:'待探测',UNKNOWN:'未知'}
const monitorMap=computed(()=>Object.fromEntries((data.value.latest_monitors||[]).map((m:any)=>[m.id,m])))
const healthy=computed(()=>data.value.health_rate==null?'—':Number(data.value.health_rate).toFixed(1))
const recentSuccess=computed(()=>results.value.length?(results.value.filter(r=>r.success).length/results.value.length*100).toFixed(1):'—')
const slowest=computed(()=>[...results.value].filter(r=>r.latency_ms!=null).sort((a,b)=>b.latency_ms-a.latency_ms).slice(0,5))
const fmtTime=(v:any)=>v?new Date(v).toLocaleTimeString('zh-CN',{hour12:false}):'--:--:--'
const color=(status:string)=>({UP:'#30e6a1',DOWN:'#ff596c',DEGRADED:'#ffbd45',MAINTENANCE:'#43a9ff',PENDING:'#7d91ac'}[status]||'#7d91ac')
function renderCharts(){if(!trendEl.value||!typeEl.value)return;trend??=echarts.init(trendEl.value);typeChart??=echarts.init(typeEl.value);const ordered=[...results.value].reverse();trend.setOption({backgroundColor:'transparent',grid:{left:42,right:18,top:22,bottom:28},tooltip:{trigger:'axis',backgroundColor:'#0b2441eF',borderColor:'#2476a8',textStyle:{color:'#d9f5ff'}},xAxis:{type:'category',data:ordered.map(r=>fmtTime(r.checked_at)),axisLine:{lineStyle:{color:'#244e70'}},axisLabel:{color:'#6f9bbb',interval:Math.max(0,Math.floor(ordered.length/7))}},yAxis:{type:'value',name:'ms',nameTextStyle:{color:'#688dab'},splitLine:{lineStyle:{color:'#163a57'}},axisLabel:{color:'#6f9bbb'}},series:[{type:'line',smooth:true,symbol:'none',data:ordered.map(r=>r.latency_ms),lineStyle:{color:'#28d7ff',width:2},areaStyle:{color:new echarts.graphic.LinearGradient(0,0,0,1,[{offset:0,color:'#20cfff66'},{offset:1,color:'#20cfff05'}])}}]});const counts:any={};for(const m of data.value.latest_monitors||[])counts[m.type]=(counts[m.type]||0)+1;typeChart.setOption({tooltip:{trigger:'item',backgroundColor:'#0b2441',borderColor:'#2476a8',textStyle:{color:'#fff'}},legend:{bottom:0,textStyle:{color:'#82adca'}},series:[{type:'pie',radius:['48%','70%'],center:['50%','44%'],label:{show:false},itemStyle:{borderColor:'#07182b',borderWidth:3},data:Object.entries(counts).map(([name,value],i)=>({name,value,itemStyle:{color:['#28d7ff','#30e6a1','#9479ff','#ffbd45','#ff6e8b','#3f8cff'][i%6]}}))}]})}
async function load(){if(stopped)return;const version=++requestVersion;try{const [summary,recent,slaReport]=await Promise.all([client.get('/dashboard/summary/'),client.get('/monitor-results/',{params:{ordering:'-checked_at',page_size:80}}),client.get('/reports/sla/',{params:{days:1}})]);if(stopped||version!==requestVersion)return;data.value=summary.data;results.value=recent.data.results||recent.data;sla.value=slaReport.data.results||[];updated.value=fmtTime(summary.data.snapshot_at||new Date());error.value='';await nextTick();renderCharts()}catch(e:any){if(!stopped&&version===requestVersion)error.value=e.response?.data?.message||'数据连接异常'}}
function scheduleLoad(){if(stopped||reloadTimer)return;reloadTimer=window.setTimeout(()=>{reloadTimer=undefined;load()},250)}
function connect(){const token=localStorage.getItem('access_token');if(!token||stopped)return;const scheme=location.protocol==='https:'?'wss':'ws';socket=new WebSocket(`${scheme}://${location.host}/ws/v1/status/?token=${encodeURIComponent(token)}`);socket.onopen=()=>{connected.value=true;if(reconnectTimer)clearTimeout(reconnectTimer)};socket.onclose=()=>{connected.value=false;if(!stopped)reconnectTimer=window.setTimeout(connect,3000)};socket.onerror=()=>socket?.close();socket.onmessage=(event)=>{try{const message=JSON.parse(event.data);if(message.type==='monitor.result')scheduleLoad()}catch{scheduleLoad()}}}
function toggleFull(){document.fullscreenElement?document.exitFullscreen():root.value?.requestFullscreen()}
function resize(){trend?.resize();typeChart?.resize()}
onMounted(async()=>{stopped=false;load();connect();try{await loadSystemSettings()}catch{systemSettings.monitor_wall_refresh_seconds=10}if(stopped)return;timer=window.setInterval(load,Math.max(5,Number(systemSettings.monitor_wall_refresh_seconds)||10)*1000);clock=window.setInterval(()=>now.value=new Date(),1000);window.addEventListener('resize',resize)})
onBeforeUnmount(()=>{stopped=true;requestVersion++;if(timer)clearInterval(timer);if(clock)clearInterval(clock);if(reconnectTimer)clearTimeout(reconnectTimer);if(reloadTimer)clearTimeout(reloadTimer);socket?.close();trend?.dispose();typeChart?.dispose();window.removeEventListener('resize',resize)})
</script>

<template><div ref="root" class="wall">
  <div class="grid-bg"></div><header><div class="header-side"><span class="signal" :class="{on:connected}"><i/>{{connected?'实时链路 ONLINE':'定时同步'}}</span></div><div class="title"><i></i><div><h1>{{systemSettings.monitor_wall_title}}</h1><p>HELI DATA · BUSINESS OBSERVABILITY COMMAND CENTER</p></div><i></i></div><div class="header-side right"><button @click="toggleFull">⛶ 全屏</button><div class="clock"><b>{{now.toLocaleTimeString('zh-CN',{hour12:false})}}</b><span>{{now.toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit'})}}</span></div></div></header>
  <div v-if="error" class="error-banner">{{error}}</div>
  <main>
    <section class="kpis panel"><div class="kpi"><span>业务系统</span><b>{{data.businesses_total||0}}</b><small>BUSINESS</small></div><div class="kpi"><span>监控任务</span><b>{{data.monitors_total||0}}</b><small>MONITORS</small></div><div class="kpi healthy"><span>整体健康度</span><b>{{healthy}}<em v-if="healthy!=='—'">%</em></b><small>HEALTH INDEX</small></div><div class="kpi"><span>24H 探测</span><b>{{data.probe_stats_24h?.total||0}}</b><small>PROBES</small></div><div class="kpi success"><span>24H 成功率</span><b>{{data.probe_stats_24h?.success_rate??'—'}}<em>%</em></b><small>SUCCESS RATE</small></div><div class="kpi alarm"><span>24H 失败</span><b>{{data.probe_stats_24h?.failed||0}}</b><small>FAILED PROBES</small></div><div class="kpi"><span>平均响应</span><b>{{data.probe_stats_24h?.average_latency_ms==null?'—':Number(data.probe_stats_24h.average_latency_ms).toFixed(1)}}<em>ms</em></b><small>AVG LATENCY</small></div><div class="kpi alarm"><span>开放事件</span><b>{{data.open_incidents||0}}</b><small>TODAY {{data.today_incidents||0}}</small></div></section>
    <div class="dashboard-grid">
      <div class="left-col"><section class="panel block"><h2><span>监控状态矩阵</span><small>STATUS MATRIX</small></h2><div class="state-matrix"><div v-for="s in ['UP','DOWN','DEGRADED','MAINTENANCE','PAUSED','PENDING','UNKNOWN']" :key="s"><i :style="{background:color(s),boxShadow:`0 0 12px ${color(s)}`}"/><span>{{stateText[s]}}</span><b>{{data.states?.[s]||0}}</b></div></div></section><section class="panel block type-block"><h2><span>探测类型分布</span><small>PROBE TYPES</small></h2><div ref="typeEl" class="chart"></div></section></div>
      <div class="center-col"><section class="panel block trend-block"><h2><span>实时响应趋势</span><small>RESPONSE LATENCY · LATEST 80 SAMPLES</small></h2><div ref="trendEl" class="trend-chart"></div></section><section class="panel block topology"><h2><span>业务健康拓扑</span><small>LIVE MONITOR NODES</small></h2><div class="nodes"><div v-for="m in data.latest_monitors" :key="m.id" class="node" :class="m.status.toLowerCase()"><span class="pulse"></span><b>{{m.name}}</b><small>{{m.type}} · {{m.latency_ms==null?'—':m.latency_ms+' ms'}}</small></div></div></section></div>
      <div class="right-col"><section class="panel block event-block"><h2><span>实时事件</span><small>ACTIVE INCIDENTS</small></h2><div v-if="!data.recent_incidents?.length" class="all-clear"><div>✓</div><b>当前无开放事件</b><span>ALL SYSTEMS OPERATIONAL</span></div><div v-else class="events"><div v-for="i in data.recent_incidents" :key="i.id"><span :class="i.severity.toLowerCase()">{{i.severity}}</span><b>{{i.title}}</b><small>{{i.business}} · {{fmtTime(i.opened_at)}}</small></div></div></section><section class="panel block stream-block"><h2><span>实时探测流</span><small>LIVE PROBE STREAM</small></h2><div class="stream"><div v-for="r in results.slice(0,9)" :key="r.id"><i :class="r.success?'ok':'fail'"/><span>{{monitorMap[r.monitor]?.name||'探测任务'}}</span><em>{{r.latency_ms==null?'—':r.latency_ms+' ms'}}</em><small>{{fmtTime(r.checked_at)}}</small></div></div></section></div>
    </div>
    <div class="intel-grid">
      <section class="panel block sla-block"><h2><span>24H SLA 可用率</span><small>BUSINESS SERVICE LEVEL</small></h2><div class="sla-list"><div v-for="s in sla.slice(0,8)" :key="s.monitor_id"><div><b>{{s.monitor_name}}</b><small>{{s.business_name}} · {{s.samples}} 个样本</small></div><span :class="Number(s.availability)<99?'warn':''">{{s.availability==null?'—':Number(s.availability).toFixed(3)+'%'}}</span><em><i :style="{width:(s.availability||0)+'%'}"/></em></div></div></section>
      <section class="panel block inventory-block"><h2><span>全量监控清单</span><small>ALL ACTIVE MONITORS</small></h2><div class="inventory"><div v-for="m in data.latest_monitors" :key="m.id"><i :style="{background:color(m.status)}"/><span><b>{{m.name}}</b><small>{{m.business}}</small></span><em>{{m.type}}</em><strong>{{stateText[m.status]||m.status}}</strong><small>{{m.latency_ms==null?'—':m.latency_ms+' ms'}}</small></div></div></section>
      <section class="panel block perf-block"><h2><span>性能热点 TOP 5</span><small>SLOWEST RECENT PROBES</small></h2><div class="slow-list"><div v-for="(r,index) in slowest" :key="r.id"><b>0{{index+1}}</b><span>{{monitorMap[r.monitor]?.name||'探测任务'}}</span><em>{{Number(r.latency_ms).toFixed(2)}} ms</em></div></div><div class="sample-rate"><span>最近 {{results.length}} 个样本成功率</span><b>{{recentSuccess}}%</b></div></section>
    </div>
  </main><footer><span>服务端快照 {{updated||'--:--:--'}}</span><b>HELI MONITOR · 全域业务可用性监控</b><span>实时推送 · 10s 兜底同步</span></footer>
</div></template>

<style scoped>
